65. /**
66.  * This Verticle is responsible for configuring the GraphQL server, setting up routes, metrics etc
67.  * that will be deployed inside vert.x.
68.  */
69. @Slf4j
70. public class GraphQLServer extends AbstractVerticle {
71. 
72.   private final RootGraphqlModel model;
73.   private final Optional<String> snowflakeUrl;
74.   private ServerConfig config;
75. 
76.   public static void main(String[] args) {
77.     var prometheusMeterRegistry = new PrometheusMeterRegistry(PrometheusConfig.DEFAULT);
78.     var metricsOptions =
79.         new MicrometerMetricsOptions()
80.             .setMicrometerRegistry(prometheusMeterRegistry)
81.             .setEnabled(true);
82.     var vertx = Vertx.vertx(new VertxOptions().setMetricsOptions(metricsOptions));
83. 
84.     vertx.deployVerticle(
85.         new GraphQLServer(),
86.         res -> {
87.           if (res.succeeded()) {
88.             System.out.println("Deployment id is: " + res.result());
89.           } else {
90.             System.out.println("Deployment failed!");
91.           }
92.         });
93.   }
94. 
95.   public GraphQLServer() {
96.     this(readModel(), null, readSnowflakeUrl());
97.   }
98. 
99.   @SneakyThrows
100.   private static Optional<String> readSnowflakeUrl() {
101.     // How to check for snowflake ?
102.     File snowflakeConfig = new File("snowflake-config.json");
103.     Map map = null;
104.     if (snowflakeConfig.exists()) {
105.       map = getObjectMapper().readValue(snowflakeConfig, Map.class);
106.       if (map.isEmpty()) return Optional.empty();
107.     } else {
108.       return Optional.empty();
109.     }
110. 
111.     String url = (String) map.get("url");
112.     if (Strings.isNullOrEmpty(url)) {
113.       log.warn("Url must be specified in the snowflake engine");
114.       return Optional.empty();
115.     }
116.     return Optional.of(url);
117.   }
118. 
119.   public GraphQLServer(RootGraphqlModel model, ServerConfig config, Optional<String> snowflakeUrl) {
120.     this.model = model;
121.     this.config = config;
122.     this.snowflakeUrl = snowflakeUrl;
123.   }
124. 
125.   public static class ModelContainer {
126.     public RootGraphqlModel model;
127.   }
128. 
129.   @SneakyThrows
130.   private static RootGraphqlModel readModel() {
131.     return getObjectMapper().readValue(new File("server-model.json"), ModelContainer.class).model;
132.   }
133. 
134.   public static ObjectMapper getObjectMapper() {
135.     var objectMapper = new ObjectMapper();
136. 
137.     // Register the custom deserializer module
138.     var module = new SimpleModule();
139.     module.addDeserializer(String.class, new JsonEnvVarDeserializer());
140.     objectMapper.registerModule(module);
141.     return objectMapper;
142.   }
143. 
144.   private Future<JsonObject> loadConfig() {
145.     Promise<JsonObject> promise = Promise.promise();
146.     vertx
147.         .fileSystem()
148.         .readFile(
149.             "server-config.json",
150.             result -> {
151.               if (result.succeeded()) {
152.                 try {
153.                   var objectMapper = new ObjectMapper();
154.                   var module = new SimpleModule();
155.                   module.addDeserializer(String.class, new JsonEnvVarDeserializer());
156.                   objectMapper.registerModule(module);
157.                   var configMap = objectMapper.readValue(result.result().toString(), Map.class);
158.                   var config = new JsonObject(configMap);
159.                   promise.complete(config);
160.                 } catch (Exception e) {
161.                   e.printStackTrace();
162.                   promise.fail(e);
163.                 }
164.               } else {
165.                 promise.fail(result.cause());
166.               }
167.             });
168.     return promise.future();
169.   }
170. 
171.   @Override
172.   public void start(Promise<Void> startPromise) {
173.     if (this.config == null) {
174.       // Config not provided, load from file
175.       loadConfig()
176.           .onComplete(
177.               ar -> {
178.                 if (ar.succeeded()) {
179.                   this.config = new ServerConfig(ar.result());
180.                   trySetupServer(startPromise);
181.                 } else {
182.                   startPromise.fail(ar.cause());
183.                 }
184.               });
185.     } else {
186.       // Config already provided, proceed with setup
187.       trySetupServer(startPromise);
188.     }
189.   }
190. 
191.   protected void trySetupServer(Promise<Void> startPromise) {
192.     try {
193.       setupServer(startPromise);
194.     } catch (Exception e) {
195.       log.error("Could not start graphql server", e);
196.       e.printStackTrace();
197.       if (!startPromise.future().isComplete()) {
198.         startPromise.fail(e);
199.       }
200.     }
201.   }
202. 
203.   protected void setupServer(Promise<Void> startPromise) {
204.     var router = Router.router(vertx);
205.     router.route().handler(LoggerHandler.create());
206. 
207.     var registry = BackendRegistries.getDefaultNow();
208.     if (registry instanceof PrometheusMeterRegistry meterRegistry) {
209.       router
210.           .route("/metrics")
211.           .handler(
212.               ctx -> {
213.                 ctx.response().putHeader("content-type", "text/plain");
214.                 ctx.response().end(meterRegistry.scrape());
215.               });
216.     }
217. 
218.     if (this.config.getGraphiQLHandlerOptions() != null) {
219.       var handlerBuilder =
220.           GraphiQLHandler.builder(vertx).with(this.config.getGraphiQLHandlerOptions());
221.       if (this.config.getAuthOptions() != null) {
222.         handlerBuilder.addingHeaders(
223.             rc -> {
224.               String token = rc.get("token");
225.               return MultiMap.caseInsensitiveMultiMap().add("Authorization", "Bearer " + token);
226.             });
227.       }
228. 
229.       var handler = handlerBuilder.build();
230.       router
231.           .route(this.config.getServletConfig().getGraphiQLEndpoint())
232.           .subRouter(handler.router());
233.     }
234. 
235.     router.errorHandler(
236.         500,
237.         ctx -> {
238.           ctx.failure().printStackTrace();
239.           ctx.response().setStatusCode(500).end();
240.         });
241. 
242.     var client = getPostgresSqlClient();
243.     Map<DatabaseType, SqlClient> clients = new HashMap<>();
244.     clients.put(DatabaseType.POSTGRES, client);
245.     clients.put(DatabaseType.DUCKDB, getDuckdbSqlClient());
246.     snowflakeUrl.map(s -> clients.put(DatabaseType.SNOWFLAKE, getSnowflakeClient(s)));
247. 
248.     var graphQL = createGraphQL(clients, startPromise);
249. 
250.     var corsHandler = toCorsHandler(this.config.getCorsHandlerOptions());
251.     router.route().handler(corsHandler);
252.     router.route().handler(BodyHandler.create());
253. 
254.     var healthCheckHandler = HealthCheckHandler.create(vertx);
255.     router.get("/health*").handler(healthCheckHandler);
256. 
257.     var handler = router.route(this.config.getServletConfig().getGraphQLEndpoint());
258.     Optional<JWTAuth> authProvider =
259.         this.config.getAuthOptions() != null
260.             ? Optional.of(JWTAuth.create(vertx, this.config.getAuthOptions()))
261.             : Optional.empty();
262.     authProvider.ifPresent(
263.         (auth) -> {
264.           // Required for adding auth on ws handler
265.           System.setProperty("io.vertx.web.router.setup.lenient", "true");
266.           handler.handler(JWTAuthHandler.create(auth));
267.         });
268.     handler
269.         .handler(GraphQLWSHandler.create(graphQL))
270.         .handler(GraphQLHandler.create(graphQL, this.config.getGraphQLHandlerOptions()));
271. 
272.     vertx
273.         .createHttpServer(this.config.getHttpServerOptions())
274.         .requestHandler(router)
275.         .listen(this.config.getHttpServerOptions().getPort())
276.         .onFailure(
277.             (e) -> {
278.               log.error("Could not start graphql server", e);
279.               if (!startPromise.future().isComplete()) {
280.                 startPromise.fail(e);
281.               }
282.             })
283.         .onSuccess(
284.             (s) -> {
285.               log.info(
286.                   "HTTP server started on port {}", this.config.getHttpServerOptions().getPort());
287.               if (!startPromise.future().isComplete()) {
288.                 startPromise.complete();
289.               }
290.             });
291.   }
292. 
293.   @SneakyThrows
294.   private SqlClient getSnowflakeClient(String url) {
295.     try {
296.       Class.forName("net.snowflake.client.jdbc.SnowflakeDriver");
297.     } catch (ClassNotFoundException e) {
298.       e.printStackTrace();
299.     }
300. 
301.     final JsonObject config =
302.         new JsonObject()
303.             .put("driver_class", "net.snowflake.client.jdbc.SnowflakeDriver")
304.             .put("url", url)
305.             .put("CLIENT_SESSION_KEEP_ALIVE", "true");
306. 
307.     JDBCPool pool = JDBCPool.pool(vertx, config);
308.     return pool;
309.   }
310. 
311.   @SneakyThrows
312.   private SqlClient getDuckdbSqlClient() {
313.     String url =
314.         "jdbc:duckdb:"; // In-memory DuckDB instance or you can specify a file path for persistence
315. 
316.     try {
317.       Class.forName("org.duckdb.DuckDBDriver");
318.     } catch (ClassNotFoundException e) {
319.       e.printStackTrace();
320.     }
321. 
322.     final JsonObject config =
323.         new JsonObject()
324.             .put("driver_class", "org.duckdb.DuckDBDriver")
325.             .put("datasourceName", "pool-name")
326.             .put("url", url)
327.             //        .put("max_pool_size", 1)
328.             .put(DuckDBDriver.JDBC_STREAM_RESULTS, String.valueOf(true));
329. 
330.     JDBCPool pool = JDBCPool.pool(vertx, config);
331. 
332.     return pool;
333.   }
334. 
335.   private CorsHandler toCorsHandler(CorsHandlerOptions corsHandlerOptions) {
336.     var corsHandler =
337.         corsHandlerOptions.getAllowedOrigin() != null
338.             ? CorsHandler.create(corsHandlerOptions.getAllowedOrigin())
339.             : CorsHandler.create();
340. 
341.     // Empty allowed origin list means nothing is allowed vs null which is permissive
342.     if (corsHandlerOptions.getAllowedOrigins() != null) {
343.       corsHandler.addOrigins(corsHandlerOptions.getAllowedOrigins());
344.     }
345. 
346.     return corsHandler
347.         .allowedMethods(
348.             corsHandlerOptions.getAllowedMethods().stream()
349.                 .map(HttpMethod::valueOf)
350.                 .collect(Collectors.toSet()))
351.         .allowedHeaders(corsHandlerOptions.getAllowedHeaders())
352.         .exposedHeaders(corsHandlerOptions.getExposedHeaders())
353.         .allowCredentials(corsHandlerOptions.isAllowCredentials())
354.         .maxAgeSeconds(corsHandlerOptions.getMaxAgeSeconds())
355.         .allowPrivateNetwork(corsHandlerOptions.isAllowPrivateNetwork());
356.   }
357. 
358.   private SqlClient getPostgresSqlClient() {
359.     return PgPool.client(
360.         vertx,
361.         this.config.getPgConnectOptions(),
362.         new PgPoolOptions(this.config.getPoolOptions()).setPipelined(true));
363.   }
364. 
365.   public GraphQL createGraphQL(Map<DatabaseType, SqlClient> client, Promise<Void> startPromise) {
366.     try {
367.       var vertxJdbcClient = new VertxJdbcClient(client);
368.       var graphQL =
369.           model.accept(
370.               new GraphQLEngineBuilder.Builder()
371.                   .withMutationConfiguration(new MutationConfigurationImpl(model, vertx, config))
372.                   .withSubscriptionConfiguration(
373.                       new SubscriptionConfigurationImpl(
374.                           model, vertx, config, startPromise, vertxJdbcClient))
375.                   .withExtendedScalarTypes(List.of(CustomScalars.GRAPHQL_BIGINTEGER))
376.                   .build(),
377.               new VertxContext(vertxJdbcClient));
378.       var meterRegistry = BackendRegistries.getDefaultNow();
379.       if (meterRegistry != null) {
380.         graphQL.instrumentation(new MicrometerInstrumentation(meterRegistry));
381.       }
382.       return graphQL.build();
383.     } catch (Exception e) {
384.       startPromise.fail(e.getMessage());
385.       log.error("Unable to create GraphQL", e);
386.       throw e;
387.     }
388.   }
389. }
