package com.datasqrl.graphql;

import graphql.schema.DataFetcher;
import graphql.schema.DataFetchingEnvironment;
import io.vertx.core.Promise;
import java.util.concurrent.CompletableFuture;
import java.util.function.BiConsumer;

public class VertxDataFetcher<T> implements DataFetcher<CompletableFuture<T>> {
  private final BiConsumer<DataFetchingEnvironment, Promise<T>> handler;

  public VertxDataFetcher(BiConsumer<DataFetchingEnvironment, Promise<T>> handler) {
    this.handler = handler;
  }

  public static <T> VertxDataFetcher<T> create(BiConsumer<DataFetchingEnvironment, Promise<T>> handler) {
    return new VertxDataFetcher<>(handler);
  }

  @Override
  public CompletableFuture<T> get(DataFetchingEnvironment environment) throws Exception {
    CompletableFuture<T> completableFuture = new CompletableFuture<>();
    Promise<T> promise = Promise.promise();
    promise.future().onComplete(ar -> {
      if (ar.succeeded()) {
        completableFuture.complete(ar.result());
      } else {
        completableFuture.completeExceptionally(ar.cause());
      }
    });
    try {
      handler.accept(environment, promise);
    } catch (Exception e) {
      if (!promise.future().isComplete()) {
        promise.fail(e);
      }
    }
    return completableFuture;
  }
}

