public class SqrlLauncher {

  public static void main(String[] args) {
    var prometheusMeterRegistry = new PrometheusMeterRegistry(PrometheusConfig.DEFAULT);
    io.micrometer.core.instrument.Metrics.addRegistry(prometheusMeterRegistry);
    var metricsOptions =
        new MicrometerMetricsOptions()
            .setEnabled(true);
    VertxOptions options = new VertxOptions().setMetricsOptions(metricsOptions);
    Vertx vertx = Vertx.vertx(options);
    vertx.deployVerticle(new GraphQLServer())
        .onComplete(res -> {
          if (res.succeeded()) {
            System.out.println("Deployment id is: " + res.result());
          } else {
            System.out.println("Deployment failed!");
            res.cause().printStackTrace();
          }
        });
  }
}

