import io.vertx.core.Vertx;
import io.vertx.sqlclient.Pool;
import io.vertx.sqlclient.PoolOptions;
import java.lang.reflect.Proxy;

public interface PgPool extends Pool {

  static PgPool pool(Vertx vertx, PgConnectOptions connectOptions, PoolOptions poolOptions) {
    Pool delegate = PgBuilder.client()
        .with(poolOptions)
        .connectingTo(connectOptions)
        .using(vertx)
        .build();
    return (PgPool) Proxy.newProxyInstance(
        PgPool.class.getClassLoader(),
        new Class<?>[]{PgPool.class},
        (proxy, method, args) -> {
          try {
            return method.invoke(delegate, args);
          } catch (java.lang.reflect.InvocationTargetException e) {
            throw e.getCause();
          }
        });
  }
}

