     var options =
         new WebSocketConnectOptions()
             .setPort(serverConfig.getHttpServerOptions().getPort())
             .setHost("localhost")
             .setURI("/graphql")
             .addHeader("Authorization", "Bearer badToken");

     vertx
         .createHttpClient()
         .webSocket(
             options,
             wsResult -> {
               if (wsResult.succeeded()) {
                 testContext.failNow("Should fail");
               } else {
                 testContext.completeNow();
               }
             });
   }

